using System.Data;
namespace StokTakipUygulamasi;
internal record Alan(string Key,string Label,int X,int Y,int Width=170,string Kind="text",bool Required=true,string? Lookup=null);
internal class KayitFormu:Form
{
    readonly string table,key,sort; readonly Alan[] fields; readonly Dictionary<string,Control> inputs=new();readonly DataGridView grid;readonly TextBox? search;readonly Session? session;long selected;
    internal KayitFormu(string title,string table,string key,string sort,Alan[] fields,int width=960,int top=145,bool product=false,Session? session=null)
    {
        this.table=table;this.key=key;this.sort=sort;this.fields=fields;this.session=session;
        int columns=fields.Length==1?1:3;int rows=(fields.Length+columns-1)/columns;
        // Place short fields first, keeping multiline fields in the same consistent grid.
        int headerHeight=fields.Length==1?148:rows*76+88;
        Ui.Setup(this,title,fields.Length==1?580:1080,Math.Max(600,headerHeight+(product?420:390)));
        KeyPreview=true;var root=UiLayout.Root(this,4);UiLayout.Row(root,0,52);UiLayout.Row(root,1,headerHeight);UiLayout.Row(root,2,80);UiLayout.Row(root,3,100,false);
        UiLayout.Add(root,UiLayout.Heading(title),0,0);
        var group=UiLayout.Card(columns,rows+1);UiLayout.Add(root,group,0,1,margin:new Padding(0,0,0,12));
        for(int i=0;i<rows;i++)UiLayout.Row(group,i,76);UiLayout.Row(group,rows,100,false);
        int index=0;foreach(var f in fields){Control c=f.Kind switch{
            "phone"=>UiLayout.Phone(),"multi"=>UiLayout.Text(true),"number"=>new NumericUpDown{Maximum=int.MaxValue},"money"=>new NumericUpDown{Maximum=99999999.99m,DecimalPlaces=2,Increment=0.01m,ThousandsSeparator=true},"combo"=>new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList},_=>UiLayout.Text()};c.Name=f.Key;if(f.Kind=="password")((TextBox)c).PasswordChar='*';inputs.Add(f.Key,c);
            Control content=c;if(product&&f.Key=="kategori_id"){var pair=UiLayout.Table(2,1,Theme.Surface);UiLayout.Col(pair,0,100,false);UiLayout.Col(pair,1,44);UiLayout.Add(pair,c,0,0,margin:new Padding(0,0,8,0));UiLayout.Add(pair,UiLayout.Button("+",()=>{using var dialog=new frmKategoriIslemleri();dialog.ShowDialog(this);FillLookups();Reload();}),1,0);content=pair;}
            UiLayout.Add(group,UiLayout.Field(f.Label.TrimEnd(':'),content),index%columns,index/columns,margin:new Padding(index%columns==0?0:6,0,index%columns==columns-1?0:6,12));index++;}
        var actions=UiLayout.Table(4,1,Theme.Surface);UiLayout.Add(group,actions,0,rows,columns);
        UiLayout.Add(actions,UiLayout.Button("Yeni kayıt",Clear),0,0,margin:new Padding(0,0,6,0));UiLayout.Add(actions,UiLayout.Button("Ekle",()=>Save(false),true),1,0,margin:new Padding(6,0,6,0));UiLayout.Add(actions,UiLayout.Button("Sil",Delete,danger:true),2,0,margin:new Padding(6,0,6,0));UiLayout.Add(actions,UiLayout.Button("Güncelle",()=>Save(true)),3,0,margin:new Padding(6,0,0,0));
        var find=UiLayout.Card(1,1);find.Padding=new Padding(12,8,12,8);UiLayout.Add(root,find,0,2,margin:new Padding(0,0,0,12));search=UiLayout.Text();search.PlaceholderText="Kayıtlarda ara…";UiLayout.Add(find,UiLayout.Field("Hızlı arama  •  Ctrl+F",search),0,0);search.TextChanged+=(_,_)=>Ui.Safe(()=>{Reload();Clear();});
        var list=UiLayout.Card(1,2);UiLayout.Row(list,0,36);UiLayout.Row(list,1,100,false);UiLayout.Add(list,UiLayout.Heading("Kayıt listesi",12),0,0);grid=UiLayout.Grid();UiLayout.Add(list,grid,0,1);UiLayout.Add(root,list,0,3);grid.CellClick+=(_,e)=>{if(e.RowIndex>=0)Ui.Safe(SelectRow);};FillLookups();Reload();Clear();
        KeyDown+=(_,e)=>{if(e.Control&&e.KeyCode==Keys.F){e.SuppressKeyPress=true;search.Focus();search.SelectAll();}else if(e.KeyCode==Keys.F5){e.SuppressKeyPress=true;Ui.Safe(()=>{FillLookups();Reload();Clear();});}};
    }
    void FillLookups(){foreach(var f in fields.Where(a=>a.Kind=="combo")){var c=(ComboBox)inputs[f.Key];var old=c.SelectedValue;c.DataSource=Db.Query(f.Lookup!);c.DisplayMember="label";c.ValueMember="id";if(old!=null)c.SelectedValue=old;}}
    void Reload(){string sql=table switch{"urunler"=>Db.Products+" ORDER BY u.urun_adi", "personeller"=>"SELECT p.id,p.ad,p.soyad,p.telefon,p.mail,p.adres,p.kullanici_adi,y.yetki_adi FROM personeller p JOIN yetkiler y ON y.yetki_id=p.yetki_id ORDER BY p.ad,p.soyad",_=>$"SELECT * FROM {table} ORDER BY {sort}"};var data=Db.Query(sql);var term=search?.Text.Trim()??"";if(term.Length>0){var filtered=data.Clone();var compare=System.Globalization.CultureInfo.GetCultureInfo("tr-TR").CompareInfo;foreach(DataRow row in data.Rows)if(row.ItemArray.Any(v=>compare.IndexOf(Db.Str(v),term,System.Globalization.CompareOptions.IgnoreCase)>=0))filtered.ImportRow(row);data=filtered;}Ui.Bind(grid,data);selected=0;}
    void Clear(){selected=0;grid.ClearSelection();grid.CurrentCell=null;foreach(var c in inputs.Values){switch(c){case TextBox t:t.Clear();break;case MaskedTextBox m:m.Clear();break;case NumericUpDown n:n.Value=0;break;case ComboBox b:b.SelectedIndex=b.Items.Count>0?0:-1;break;}}}
    void SelectRow(){selected=Ui.Selected(grid);var d=Db.Query($"SELECT * FROM {table} WHERE {key}=@p0",selected);if(d.Rows.Count==0){Clear();return;}var r=d.Rows[0];foreach(var f in fields){var c=inputs[f.Key];var v=r[f.Key];switch(c){case ComboBox b:b.SelectedValue=v;break;case NumericUpDown n:n.Value=f.Kind=="money"?Db.Number(v)/100m:Db.Number(v);break;case MaskedTextBox m:m.Text=Db.Str(v);break;case TextBox t:t.Text=f.Kind=="password"?"":Db.Str(v);break;}}}
    void Save(bool update){if(update&&selected==0)throw new InvalidOperationException("Güncellenecek kaydı seçiniz.");if(!update&&selected!=0)throw new InvalidOperationException("Yeni kayıt için YENİ KAYIT butonuna basınız.");var keys=new List<string>();var values=new List<object?>();foreach(var f in fields){var c=inputs[f.Key];object? value;switch(c){case ComboBox b:value=b.SelectedValue??throw new InvalidOperationException(f.Label+" seçiniz.");break;case NumericUpDown n:value=f.Kind=="money"?Db.Cents(n.Value):(long)n.Value;break;case MaskedTextBox m:value=Ui.Phone(m.Text);break;default:var s=c.Text.Trim();if(f.Kind=="password"){if(update&&s.Length==0)continue;if(c.Text.Length<8)throw new InvalidOperationException("Şifre en az 8 karakter olmalıdır.");value=Db.Password(c.Text);}else{if(f.Required&&s.Length==0)throw new InvalidOperationException(f.Label+" boş bırakılamaz.");if(f.Key=="mail"&&s.Length>0){try{if(new System.Net.Mail.MailAddress(s).Address!=s)throw new FormatException();}catch{throw new InvalidOperationException("Geçerli bir e-posta adresi giriniz.");}}value=s.Length==0?null:s;}break;}keys.Add(f.Key);values.Add(value);}
        if(table=="personeller"&&update&&selected==session!.Id&&Db.Number(values[keys.IndexOf("yetki_id")])!=1)throw new InvalidOperationException("Kendi yönetici yetkinizi kaldıramazsınız.");
        string sql;if(update){sql=$"UPDATE {table} SET "+string.Join(",",keys.Select((k,i)=>$"{k}=@p{i}"))+$" WHERE {key}=@p{values.Count}";values.Add(selected);}else sql=$"INSERT INTO {table}({string.Join(",",keys)}) VALUES({string.Join(",",keys.Select((_,i)=>"@p"+i))})";Db.Exec(sql,values.ToArray());Reload();Clear();Ui.Info(update?"Kayıt güncellendi.":"Kayıt eklendi.");}
    void Delete(){if(selected==0)throw new InvalidOperationException("Silinecek kaydı seçiniz.");if(table=="personeller"&&selected==session!.Id)throw new InvalidOperationException("Oturum açan personel silinemez.");if(!Ui.Confirm("Seçili kayıt silinsin mi?"))return;Db.Exec($"DELETE FROM {table} WHERE {key}=@p0",selected);Reload();Clear();Ui.Info("Kayıt silindi.");}
}
internal sealed class frmKategoriIslemleri:KayitFormu{public frmKategoriIslemleri():base("Kategori İşlemleri","kategoriler","kategori_id","kategori_adi",[new("kategori_adi","Kategori Adı:",30,35,210)],540,135){}}
