internal sealed class frmMusteriIslemleri:KayitFormu{public frmMusteriIslemleri():base("MÜŞTERİ İŞLEMLERİ","musteriler","id","ad_soyad",[new("ad_soyad","Ad Soyad:",5,25),new("telefon","Telefon:",5,57,140,"phone"),new("firma_adi","Firma Adı:",292,25,170,"text",false),new("mail","Mail:",292,57,170,"text",false),new("adres","Adres:",585,25,220,"multi",false)]){}}
internal sealed class frmPersonelIslemleri:KayitFormu{public frmPersonelIslemleri(Session user):base("PERSONEL İŞLEMLERİ","personeller","id","ad",[new("ad","Ad:",5,25),new("telefon","Telefon:",5,57,140,"phone"),new("kullanici_adi","Kullanıcı Adı:",5,89),new("soyad","Soyad:",292,25),new("mail","Mail:",292,57,170,"text",false),new("sifre","Şifre:",292,89,170,"password"),new("adres","Adres:",585,25,220,"multi",false),new("yetki_id","Yetki:",585,89,220,"combo",true,"SELECT yetki_id AS id,yetki_adi AS label FROM yetkiler ORDER BY yetki_id")],960,177,session:user){if(user.Role!=1)throw new UnauthorizedAccessException("Yönetici yetkisi gerekli.");}}
internal sealed class frmUrunIslemleri:KayitFormu{public frmUrunIslemleri():base("ÜRÜN İŞLEMLERİ","urunler","urun_kodu","urun_adi",[new("urun_adi","Ürün Adı:",5,25),new("aciklama","Açıklama:",5,57,170,"multi",false),new("kategori_id","Kategori:",292,25,145,"combo",true,"SELECT kategori_id AS id,kategori_adi AS label FROM kategoriler ORDER BY kategori_adi"),new("stok_adedi","Stok Adedi:",292,57,100,"number"),new("tedarikci_id","Tedarikçi:",585,25,220,"combo",true,"SELECT id,firma_adi AS label FROM tedarikciler ORDER BY firma_adi"),new("fiyat","Fiyat (₺):",585,57,130,"money")],960,167,true){}}
